                io_hits_1,
                io_hits_2,
                io_hits_3,
  input  [31:0] io_predictions_0,
                io_predictions_1,
                io_predictions_2,
                io_predictions_3,
  output [2:0]  io_validNum,
  output        io_redirect,
  output [31:0] io_redirectTarget
);

  wire isJal = io_instructions_0[6:0] == 7'h6F;
  wire redirect = isJal | io_instructions_0[6:0] == 7'h63 & io_predictions_0[0];
  wire _GEN = io_hits_0 & redirect;
  wire slotValid_1 = io_hits_0 & ~redirect & io_hits_1;
  wire isJal_1 = io_instructions_1[6:0] == 7'h6F;
  wire redirect_1 = isJal_1 | io_instructions_1[6:0] == 7'h63 & io_predictions_1[0];
  wire _GEN_0 = slotValid_1 & redirect_1;
  wire slotValid_2 = slotValid_1 & ~redirect_1 & io_hits_2;
  wire isJal_2 = io_instructions_2[6:0] == 7'h6F;
  wire redirect_2 = isJal_2 | io_instructions_2[6:0] == 7'h63 & io_predictions_2[0];
  wire _GEN_1 = slotValid_2 & redirect_2;
  wire slotValid_3 = slotValid_2 & ~redirect_2 & io_hits_3;
  wire isJal_3 = io_instructions_3[6:0] == 7'h6F;
  wire _GEN_2 =
    slotValid_3 & (isJal_3 | io_instructions_3[6:0] == 7'h63 & io_predictions_3[0]);
  assign io_validNum =
    {2'h0, io_hits_0} + {2'h0, slotValid_1} + {2'h0, slotValid_2} + {2'h0, slotValid_3};
  assign io_redirect = _GEN_2 | _GEN_1 | _GEN_0 | _GEN;
  assign io_redirectTarget =
    _GEN_2
      ? (isJal_3
           ? {{12{io_instructions_3[31]}},
              io_instructions_3[19:12],
              io_instructions_3[20],
              io_instructions_3[30:21],
              1'h0} + io_pcs_3
           : {{20{io_instructions_3[31]}},
              io_instructions_3[7],
              io_instructions_3[30:25],
              io_instructions_3[11:8],
              1'h0} + io_pcs_3)
      : _GEN_1
